//! Fixture-driven reader tests (recall `tests/unit/anki/{errors,read-fixtures,mapping,perf}.test.ts`).
//! The `palace-*` fixtures were generated by recall's `scripts/fixture-lib`; `palace.expected.json`
//! holds the counts the reader must reproduce.

use super::image::AnkiImage;
use super::read::read_package;
use super::zip::{create_zip, ZipArchive, ZipInput};
use crate::error::ErrorCode;
use crate::types::*;
use serde_json::{json, Value};

pub(super) const FIXTURES: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../../fixtures");

/// Fixture-generator ids (recall `scripts/fixture-lib/collection.ts`, `notetypes.ts`).
pub(super) mod ids {
    pub const DECK_ARABIC: i64 = 1685000000002;
    pub const DECK_PHYSICS: i64 = 1685000000005;
    pub const DECK_ANATOMY: i64 = 1685000000007;
    pub const DECK_HISTORY: i64 = 1685000000008;
    pub const PRESET_LANGUAGES: i64 = 1685000001001;
    pub const PRESET_VERBS: i64 = 1685000001002;
    pub const PRESET_SCIENCE: i64 = 1685000001003;
    pub const PRESET_MEDICINE: i64 = 1685000001004;
    pub const NT_TYPED: i64 = 1684000000003;
    pub const NT_IO: i64 = 1684000000005;
    pub const NT_VOCAB: i64 = 1684000000006;
}

pub(super) fn fixture(name: &str) -> Vec<u8> {
    std::fs::read(format!("{FIXTURES}/{name}")).unwrap_or_else(|e| panic!("fixture {name}: {e}"))
}

pub(super) fn expected() -> Value {
    serde_json::from_slice(&fixture("palace.expected.json")).unwrap()
}

pub(super) fn read_fixture(name: &str) -> AnkiImage {
    read_package(fixture(name)).unwrap_or_else(|e| panic!("read {name}: {e:?}"))
}

/// Rewrites a package: `edit(name, body)` returns the new body or None to drop the entry.
pub(super) fn rezip(bytes: Vec<u8>, mut edit: impl FnMut(&str, Vec<u8>) -> Option<Vec<u8>>) -> Vec<u8> {
    let zip = ZipArchive::open(bytes).unwrap();
    let mut out = Vec::new();
    for name in zip.names() {
        if let Some(data) = edit(&name, zip.read(&name).unwrap()) {
            out.push(ZipInput::new(name.clone(), data, name == "collection.anki21" || name == "collection.anki2"));
        }
    }
    create_zip(out).unwrap()
}

pub(super) const LAYOUTS: [(&str, PackageLayout); 4] = [
    ("palace-legacy1.apkg", PackageLayout::Legacy1),
    ("palace-legacy2.apkg", PackageLayout::Legacy2),
    ("palace-latest.apkg", PackageLayout::Latest),
    ("palace.colpkg", PackageLayout::Latest),
];

// ───────────────────────── errors.test.ts ─────────────────────────

fn code_of(bytes: Vec<u8>) -> ErrorCode {
    read_package(bytes).expect_err("expected read_package to fail").code
}

#[test]
fn broken_packages_are_rejected_cleanly() {
    for (file, code) in [
        ("broken-truncated.apkg", ErrorCode::Corrupt),
        ("broken-missing-collection.apkg", ErrorCode::Corrupt),
        ("broken-not-sqlite.apkg", ErrorCode::Corrupt),
        ("broken-too-new.apkg", ErrorCode::UnsupportedPackage),
        ("broken-not-a-zip.apkg", ErrorCode::UnsupportedPackage),
    ] {
        assert_eq!(code_of(fixture(file)), code, "{file}");
    }
}

#[test]
fn empty_input_is_not_a_package() {
    assert_eq!(code_of(Vec::new()), ErrorCode::UnsupportedPackage);
}

// ───────────────────────── read-fixtures.test.ts ─────────────────────────

fn counts_for(image: &AnkiImage, deck_id: i64, exp: &Value) -> Value {
    let today = exp["today"].as_i64().unwrap();
    let now = exp["now"].as_i64().unwrap();
    let next_day_at = exp["nextDayAt"].as_i64().unwrap();
    let own: Vec<&Card> = image.cards.iter().filter(|c| c.did == deck_id).collect();
    let deck = image.decks.iter().find(|d| d.id == deck_id).unwrap();
    let preset = &image.deck_configs.iter().find(|p| p.id == deck.config_id).unwrap().config;
    let n = own.iter().filter(|c| c.queue == CardQueue::New).count() as i64;
    let studied = if deck.today.day == today { deck.today.new } else { 0 };
    let count = |f: &dyn Fn(&Card) -> bool| own.iter().filter(|c| f(c)).count() as i64;
    json!({
        "total": own.len(),
        "new": n,
        "newLimited": 0i64.max(n.min(preset.new_per_day + deck.extend_new - studied)),
        "learnIntraday": count(&|c| c.queue == CardQueue::Learn && c.due < next_day_at),
        "learnDueNow": count(&|c| c.queue == CardQueue::Learn && c.due <= now + image.config.collapse_time),
        "interdayDue": count(&|c| c.queue == CardQueue::DayLearn && c.due <= today),
        "reviewDue": count(&|c| c.queue == CardQueue::Review && c.due <= today),
        "reviewOverdue": count(&|c| c.queue == CardQueue::Review && c.due < today),
        "reviewFuture": count(&|c| c.queue == CardQueue::Review && c.due > today),
        "suspended": count(&|c| c.queue == CardQueue::Suspended),
        "buried": count(&|c| c.queue == CardQueue::SchedBuried || c.queue == CardQueue::UserBuried),
    })
}

#[test]
fn detects_the_layout_and_schema() {
    let exp = expected();
    for (file, layout) in LAYOUTS {
        let image = read_fixture(file);
        assert_eq!(image.layout, layout, "{file}");
        assert_eq!(image.schema_version, if layout == PackageLayout::Latest { 18 } else { 11 }, "{file}");
        assert_eq!(image.crt, exp["crt"].as_i64().unwrap());
    }
}

#[test]
fn has_the_generator_totals() {
    let exp = expected();
    let t = &exp["totals"];
    for (file, _) in LAYOUTS {
        let image = read_fixture(file);
        assert_eq!(image.notes.len() as i64, t["notes"], "{file}");
        assert_eq!(image.cards.len() as i64, t["cards"], "{file}");
        assert_eq!(image.revlog.len() as i64, t["revlog"], "{file}");
        assert_eq!(image.media.len() as i64, t["media"], "{file}");
        assert_eq!(image.notetypes.len() as i64, t["notetypes"], "{file}");
        assert_eq!(image.decks.len() as i64, t["decksAfterImport"], "{file}");
        assert_eq!(image.deck_configs.len() as i64, t["deckConfigs"], "{file}");
        assert_eq!(
            image.cards.iter().filter(|c| c.data.s.is_some() && c.data.d.is_some()).count() as i64,
            t["fsrsCards"],
            "{file}"
        );
        assert_eq!(image.notes.iter().filter(|n| n.tags.iter().any(|t| t == "leech")).count() as i64, t["leechNotes"], "{file}");
    }
}

#[test]
fn per_deck_due_counts_equal_ankis_on_the_collection_day() {
    let exp = expected();
    for (file, _) in LAYOUTS {
        let image = read_fixture(file);
        for (name, counts) in exp["decks"].as_object().unwrap() {
            let deck = image.decks.iter().find(|d| &d.name == name).unwrap_or_else(|| panic!("{file}: deck {name}"));
            assert_eq!(counts_for(&image, deck.id, &exp), *counts, "{file}: {name}");
        }
    }
}

#[test]
fn specific_cards_have_their_exact_due_days() {
    let exp = expected();
    for (file, _) in LAYOUTS {
        let image = read_fixture(file);
        for c in exp["cards"].as_array().unwrap() {
            let card = image.cards.iter().find(|x| x.id == c["id"].as_i64().unwrap()).unwrap();
            let deck = image.decks.iter().find(|d| d.id == card.did).unwrap();
            let got = json!({ "label": c["label"], "id": card.id, "deck": deck.name, "type": card.ctype, "queue": card.queue, "due": card.due, "ivl": card.ivl, "odue": card.odue });
            assert_eq!(got, *c, "{file}");
        }
    }
}

#[test]
fn returns_filtered_deck_cards_home_and_drops_the_filtered_deck_with_a_warning() {
    for (file, _) in LAYOUTS {
        let image = read_fixture(file);
        assert!(!image.decks.iter().any(|d| d.filtered));
        assert!(!image.decks.iter().any(|d| d.name == "Filtered Deck 1"));
        assert!(image.cards.iter().all(|c| c.odid == 0 && c.odue == 0));
        assert!(image.cards.iter().all(|c| c.due > -100000 + 100));
        assert!(
            image.warnings.iter().any(|w| w.contains("Filtered deck \"Filtered Deck 1\" was not imported; 10 card(s)")),
            "{file}: {:?}",
            image.warnings
        );
    }
}

#[test]
fn reads_the_collection_config() {
    for (file, _) in LAYOUTS {
        let c = read_fixture(file).config;
        assert_eq!(c.sched_ver, 2, "{file}");
        assert!(c.sched2021);
        assert_eq!(c.rollover, 4);
        assert_eq!(c.creation_offset, Some(0));
        assert!(c.fsrs);
        assert_eq!(c.collapse_time, 1200);
    }
}

pub(super) fn strip_decks(image: &AnkiImage) -> Vec<super::image::AnkiDeck> {
    let mut v: Vec<_> = image
        .decks
        .iter()
        .cloned()
        .map(|mut d| {
            d.original_json = None;
            d
        })
        .collect();
    v.sort_by_key(|d| d.id);
    v
}

pub(super) fn strip_presets(image: &AnkiImage) -> Vec<super::image::AnkiDeckConfig> {
    let mut v: Vec<_> = image
        .deck_configs
        .iter()
        .cloned()
        .map(|mut p| {
            p.original_json = None;
            p
        })
        .collect();
    v.sort_by_key(|p| p.id);
    v
}

#[test]
fn all_layouts_decode_to_the_same_collection() {
    let images: Vec<AnkiImage> = LAYOUTS.iter().map(|(f, _)| read_fixture(f)).collect();
    let first = &images[0];
    for other in &images[1..] {
        assert_eq!(other.notes, first.notes);
        assert_eq!(other.cards, first.cards);
        assert_eq!(other.revlog, first.revlog);
        assert_eq!(other.notetypes, first.notetypes);
        assert_eq!(strip_decks(other), strip_decks(first));
        assert_eq!(strip_presets(other), strip_presets(first));
        assert_eq!(other.media.keys().collect::<Vec<_>>(), first.media.keys().collect::<Vec<_>>());
    }
}

