const MAPPING_FILES: [&str; 2] = ["palace-legacy2.apkg", "palace-latest.apkg"];

#[test]
fn note_types_kinds_fields_templates_stock_kinds() {
    for file in MAPPING_FILES {
        let image = read_fixture(file);
        let by_name = |n: &str| image.notetypes.iter().find(|nt| nt.name == n).unwrap_or_else(|| panic!("{file}: {n}"));
        let mut names: Vec<&str> = image.notetypes.iter().map(|nt| nt.name.as_str()).collect();
        names.sort();
        assert_eq!(
            names,
            ["Basic", "Basic (and reversed card)", "Basic (type in the answer)", "Cloze", "Image Occlusion", "Vocab"]
        );
        let cloze = by_name("Cloze");
        assert_eq!(cloze.kind, NotetypeKind::Cloze);
        assert_eq!(cloze.templates[0].qfmt, "{{cloze:Text}}");
        assert_eq!(cloze.templates[0].afmt, "{{cloze:Text}}<br>\n{{Back Extra}}");
        let io = by_name("Image Occlusion");
        assert_eq!(io.kind, NotetypeKind::Cloze);
        assert_eq!(
            io.fields.iter().map(|f| f.name.as_str()).collect::<Vec<_>>(),
            ["Occlusion", "Image", "Header", "Back Extra", "Comments"]
        );
        assert_eq!(io.config.original_stock_kind, Some(6));
        assert_eq!(io.config.builtin, Some(BuiltinKind::ImageOcclusion));
        assert_eq!(io.config.occlusion_mode, Some(OcclusionMode::HideAll));
        let vocab = by_name("Vocab");
        assert_eq!(vocab.id, ids::NT_VOCAB);
        assert_eq!(vocab.sort_field, 1);
        assert_eq!(
            vocab.fields[0].config,
            FieldConfig {
                sticky: false,
                rtl: true,
                font: "Noto Naskh Arabic".into(),
                size: 32,
                description: String::new(),
                plain_text: false,
                collapsed: false
            }
        );
        assert_eq!(vocab.fields[2].config.description, "a short sentence using the word");
        assert!(vocab.fields[3].config.collapsed);
        assert_eq!(vocab.templates.iter().map(|t| t.name.as_str()).collect::<Vec<_>>(), ["Recognition", "Usage"]);
        assert!(vocab.templates[1].qfmt.contains("{{#Example}}"));
        assert_eq!(vocab.config.req, vec![Requirement(0, ReqKind::Any, vec![0, 3]), Requirement(1, ReqKind::Any, vec![2])]);
        assert_eq!(vocab.config.builtin, None);
        assert_eq!(by_name("Basic").config.original_stock_kind, Some(1));
    }
}

#[test]
fn the_empty_example_field_produced_no_usage_card() {
    for file in MAPPING_FILES {
        let image = read_fixture(file);
        let without_example: Vec<&Note> =
            image.notes.iter().filter(|n| n.ntid == ids::NT_VOCAB && n.fields[2].is_empty()).collect();
        assert!(without_example.len() > 10, "{file}");
        for n in without_example {
            let ords: Vec<i64> = image.cards.iter().filter(|c| c.nid == n.id).map(|c| c.ord).collect();
            assert_eq!(ords, vec![0]);
        }
    }
}

#[test]
fn decks_names_presets_descriptions_counters() {
    for file in MAPPING_FILES {
        let image = read_fixture(file);
        let deck = |id: i64| image.decks.iter().find(|d| d.id == id).unwrap();
        let arabic = deck(ids::DECK_ARABIC);
        assert_eq!(arabic.name, "Languages::Arabic");
        assert_eq!(arabic.config_id, ids::PRESET_LANGUAGES);
        assert!(!arabic.filtered);
        assert!(arabic.description.contains("Modern Standard Arabic"));
        let anatomy = deck(ids::DECK_ANATOMY);
        assert!(anatomy.today.day > 1000);
        assert!(anatomy.today.new + anatomy.today.rev + anatomy.today.lrn > 0);
        assert_eq!(deck(ids::DECK_HISTORY).extend_new, 2);
        assert_eq!(deck(1).name, "Default");
    }
}

#[test]
fn deck_options_steps_fsrs_params_desired_retention_leech_bury() {
    for file in MAPPING_FILES {
        let image = read_fixture(file);
        let preset = |id: i64| &image.deck_configs.iter().find(|p| p.id == id).unwrap().config;
        let sci = preset(ids::PRESET_SCIENCE);
        assert_eq!(sci.scheduler, SchedulerKind::Fsrs);
        assert_eq!(sci.fsrs_params.len(), 21);
        assert_eq!(sci.fsrs_params[20], 0.1511, "{file}"); // generator: 0.1542 × 0.98, 4 dp
        assert_eq!(sci.desired_retention, 0.88);
        assert_eq!(sci.historical_retention, 0.87);
        assert_eq!(sci.review_order, ReviewOrder::RelativeOverdue);
        assert!(sci.show_timer);
        assert_eq!(sci.max_answer_seconds, 90);
        let med = preset(ids::PRESET_MEDICINE);
        assert_eq!(med.fsrs_params.len(), 19);
        assert_eq!(med.fsrs_params[0], 0.40255);
        assert_eq!(med.desired_retention, 0.92);
        assert_eq!(med.learn_steps, vec![1.0, 10.0, 60.0]);
        assert_eq!(med.relearn_steps, vec![10.0]);
        assert_eq!((med.leech_action, med.leech_threshold), (LeechAction::Suspend, 6));
        assert!(med.bury_siblings_new && med.bury_siblings_review && !med.bury_siblings_interday);
        assert_eq!(med.maximum_interval, 3650);
        assert_eq!(med.new_gather, NewCardGather::RandomNotes);
        assert_eq!(med.new_review_mix, NewReviewMix::ReviewFirst);
        assert!(!med.autoplay_audio);
        let verbs = preset(ids::PRESET_VERBS);
        assert_eq!(verbs.learn_steps, vec![10.0, 1440.0]);
        assert_eq!(verbs.new_per_day, 3);
        assert_eq!(verbs.interday_learning_mix, NewReviewMix::ReviewFirst);
        let languages = preset(ids::PRESET_LANGUAGES);
        assert_eq!(languages.new_sort, NewCardSort::TemplateThenRandom);
        assert_eq!((languages.new_per_day, languages.reviews_per_day, languages.leech_action), (4, 200, LeechAction::Tag));
        // Loci-only fields come from the Standard preset
        let d = preset(1);
        assert_eq!(
            (d.minutes_per_day, d.auto_optimise, d.optimise_every_reviews, d.show_intervals_on_buttons),
            (20, true, 400, true)
        );
    }
}

#[test]
fn cards_keep_fsrs_memory_state_and_anki_columns() {
    for file in MAPPING_FILES {
        let image = read_fixture(file);
        let fsrs_card = image.cards.iter().find(|c| c.did == ids::DECK_PHYSICS && c.ctype == CardType::Review).unwrap();
        assert!(fsrs_card.data.s.unwrap() > 0.0);
        assert!(fsrs_card.data.d.unwrap() >= 1.0);
        assert_eq!(fsrs_card.data.dr, Some(0.88));
        assert_eq!(fsrs_card.data.decay, Some(0.151));
        assert!(fsrs_card.data.lrt.unwrap() > 1_600_000_000);
        let sm2_card = image.cards.iter().find(|c| c.did == ids::DECK_ARABIC && c.ctype == CardType::Review).unwrap();
        assert_eq!(sm2_card.data.s, None);
        assert!(sm2_card.factor >= 1300);
        assert_eq!(image.cards.iter().filter(|c| c.flags > 0).count(), 14);
        let fsrs_review = image.revlog.iter().find(|r| r.cid == fsrs_card.id && r.rtype == RevlogType::Review).unwrap();
        assert!((100..=1100).contains(&fsrs_review.factor));
    }
}

