#[test]
fn reads_the_palace_package_quickly() {
    let bytes = fixture("palace-legacy2.apkg");
    let t0 = std::time::Instant::now();
    let image = read_package(bytes).unwrap();
    let elapsed = t0.elapsed();
    eprintln!("palace-legacy2.apkg: read in {} ms", elapsed.as_millis());
    assert_eq!(image.notes.len(), 402);
    assert!(elapsed.as_secs() < 5, "read took {elapsed:?}");
}

/// recall's perf test builds a 50 000–100 000-note collection with `scripts/fixture-lib`
/// (`buildLargeCollection`), which has no Rust port; this builds a comparable synthetic image
/// instead. Run by hand: `cargo test -p loci-core anki::tests_fixtures::large_collection -- --ignored --nocapture`.
#[test]
#[ignore = "builds and round-trips a 50 000-note package; run by hand for timings"]
fn large_collection_writes_and_reads_a_large_legacy_package() {
    use super::write::{write_legacy_package, WriteLegacyOptions};
    let n: usize = std::env::var("LOCI_PERF_NOTES").ok().and_then(|v| v.parse().ok()).unwrap_or(50_000);
    let mut image = read_fixture("palace-legacy2.apkg");
    let basic = image.notetypes.iter().find(|nt| nt.name == "Basic").unwrap().id;
    image.notes.clear();
    image.cards.clear();
    image.revlog.clear();
    let base_ms: i64 = 1_700_000_000_000;
    for i in 0..n as i64 {
        let nid = base_ms + i * 10;
        image.notes.push(Note {
            id: nid,
            guid: format!("g{i}"),
            ntid: basic,
            mtime: 1_700_000_000,
            usn: -1,
            tags: vec!["perf".into()],
            fields: vec![format!("front {i}"), format!("back {i}")],
        });
        image.cards.push(Card {
            id: nid + 1,
            nid,
            did: 1,
            ord: 0,
            mtime: 1_700_000_000,
            usn: -1,
            ctype: CardType::Review,
            queue: CardQueue::Review,
            due: 1000 + (i % 300),
            ivl: 10,
            factor: 2500,
            reps: 3,
            lapses: 0,
            left: 0,
            odue: 0,
            odid: 0,
            flags: 0,
            data: CardData { s: Some(12.5), d: Some(5.0), ..CardData::default() },
        });
        for k in 0..3 {
            image.revlog.push(RevlogEntry {
                id: nid + 2 + k,
                cid: nid + 1,
                usn: -1,
                ease: 3,
                ivl: 10,
                last_ivl: 5,
                factor: 2500,
                time: 4000,
                rtype: RevlogType::Review,
            });
        }
    }
    let t0 = std::time::Instant::now();
    let bytes =
        write_legacy_package(&image, WriteLegacyOptions { include_scheduling: true, include_media: false, now: None }).unwrap();
    let t1 = std::time::Instant::now();
    let back = read_package(bytes.clone()).unwrap();
    let t2 = std::time::Instant::now();
    eprintln!(
        "{n} notes: write {} ms, read {} ms, {:.1} MB",
        (t1 - t0).as_millis(),
        (t2 - t1).as_millis(),
        bytes.len() as f64 / 1e6
    );
    assert_eq!(back.notes.len(), n);
    assert_eq!(back.revlog.len(), image.revlog.len());
}
